package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveInputStream_getNextTarEntry_TriageGen1Test {

    /**
     * Helper to create a minimal valid Tar Header (512 bytes)
     * For simplicity in testing logic, we mock the stream content.
     */
    private byte[] createMockTarHeader(String name, long size) {
        byte[] header = new byte[512];
        byte[] nameBytes = name.getBytes(StandardCharsets.UTF_8);
        System.arraycopy(nameBytes, 0, header, 0, Math.min(nameBytes.length, 100));

        // Size is at offset 124 in Tar header (little endian/specific format)
        // But since we are testing the logic of the stream, we rely on the 
        // TarArchiveEntry constructor which parses the headerBuf.
        // To make TarArchiveEntry work, we need a validly formatted header.
        // In a real scenario, we'd use TarArchiveOutputStream to generate valid bytes.
        return header;
    }

    @Test
    public void testGetNextTarEntry_EOF() throws IOException {
        // Empty stream simulates immediate EOF
        InputStream is = new ByteArrayInputStream(new byte[0]);
        TarArchiveInputStream tais = new TarArchiveInputStream(is);

        // The first call to getRecord() inside getNextTarEntry will trigger hasHitEOF
        TarArchiveEntry entry = tais.getNextTarEntry();
        Assert.assertNull(entry);
    }

    @Test
    public void testGetNextTarEntry_NormalFlow() throws IOException {
        // We use a real TarArchiveOutputStream to generate valid bytes to ensure 
        // headerBuf and TarArchiveEntry logic is exercised correctly.
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        TarArchiveEntry entry1 = new TarArchiveEntry("file1.txt");
        entry1.setSize(5);
        taos.putArchiveEntry(entry1);
        taos.write("hello".getBytes());
        taos.closeArchiveEntry();

        TarArchiveEntry entry2 = new TarArchiveEntry("file2.txt");
        entry2.setSize(3);
        taos.putArchiveEntry(entry2);
        taos.write("abc".getBytes());
        taos.closeArchiveEntry();

        taos.close();

        TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));

        // First entry
        TarArchiveEntry result1 = tais.getNextTarEntry();
        Assert.assertNotNull(result1);
        Assert.assertEquals("file1.txt", result1.getName());

        // Second entry (exercises the "if (currEntry != null)" skip logic)
        TarArchiveEntry result2 = tais.getNextTarEntry();
        Assert.assertNotNull(result2);
        Assert.assertEquals("file2.txt", result2.getName());

        // Third call (EOF)
        TarArchiveEntry result3 = tais.getNextTarEntry();
        Assert.assertNull(result3);
    }

    @Test
    public void testGetNextTarEntry_GNU_LongName() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        // Create a long filename
        String longName = "this_is_a_very_long_filename_that_should_trigger_gnu_long_name_logic.txt";
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(4);
        taos.putArchiveEntry(entry);
        taos.write("test".getBytes());
        taos.closeArchiveEntry();
        taos.close();

        TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        TarArchiveEntry result = tais.getNextTarEntry();

        Assert.assertNotNull(result);
        Assert.assertEquals(longName, result.getName());
    }

    @Test
    public void testGetNextTarEntry_PaxHeader() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        TarArchiveEntry entry = new TarArchiveEntry("pax.txt");
        // Setting a pax header property (like access time) triggers isPaxHeader()
        entry.setAccessTime(new java.util.Date(123456789L));
        entry.setSize(4);
        taos.putArchiveEntry(entry);
        taos.write("data".getBytes());
        taos.closeArchiveEntry();
        taos.close();

        TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        TarArchiveEntry result = tais.getNextTarEntry();

        Assert.assertNotNull(result);
        Assert.assertEquals("pax.txt", result.getName());
    }

    @Test
    public void testGetNextTarEntry_GNUSparse() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        TarArchiveEntry entry = new TarArchiveEntry("sparse.txt");
        // In Commons Compress, sparse files are handled via specific flags/logic
        // We simulate a sparse entry if the library allows or by using the internal mechanisms
        // For the sake of coverage, we use a file that triggers the sparse detection logic
        entry.setSize(100);
        taos.putArchiveEntry(entry);
        // Writing nothing/minimal to simulate sparse-like behavior if supported by the stream
        taos.closeArchiveEntry();
        taos.close();

        TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        TarArchiveEntry result = tais.getNextTarEntry();

        Assert.assertNotNull(result);
    }

    @Test(expected = RuntimeException.class)
    public void testGetNextTarEntry_SkipFailure() throws IOException {
        // Create a stream that returns 0 on skip to trigger the RuntimeException
        InputStream failingSkipStream = new InputStream() {
            @Override
            public int read() { return -1; }
            @Override
            public long skip(long n) { return 0; } // Force failure
        };

        // We need a valid header first so currEntry is not null on the second call
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);
        TarArchiveEntry e1 = new TarArchiveEntry("e1");
        e1.setSize(10);
        taos.putArchiveEntry(e1);
        taos.write(new byte[10]);
        taos.closeArchiveEntry();
        taos.close();

        // Wrap the valid bytes with the failing stream? 
        // Actually, we can just provide a stream that fails during the skip phase.
        // To do this, we need the first entry to succeed, then the second to attempt a skip.

        // We'll use a custom InputStream that succeeds once then fails on skip
        InputStream customIs = new InputStream() {
            private int count = 0;
            private byte[] data = baos.toByteArray();

            @Override
            public int read() {
                if (count < data.length) return data[count++] & 0xff;
                return -1;
            }

            @Override
            public long skip(long n) {
                if (count > 512) return 0; // Fail after first header is read
                return n;
            }
        };

        TarArchiveInputStream tais = new TarArchiveInputStream(customIs);
        tais.getNextTarEntry(); // Succeeds first entry
        tais.getNextTarEntry(); // Should trigger skip failure
    }
}
